<div class="d-flex justify-content-between align-items-center content-heading mb-4"><div><h1>Purchases</h1><p>Warehouse-specific purchasing and supplier receiving.</p></div><a href="<?php echo e(route('admin.purchases.create')); ?>" class="btn text-white" style="background:var(--brand)"><i class="bi bi-plus-lg me-1"></i>New purchase</a></div><div class="panel p-0 overflow-hidden"><table class="table mb-0"><thead><tr><th>Purchase no.</th><th>Date</th><th>Warehouse</th><th>Supplier</th><th>Items</th><th>Total</th><th>Status</th></tr></thead><tbody><?php $__empty_1 = true; $__currentLoopData = $purchases; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $purchase): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?><tr><td class="fw-semibold"><?php echo e($purchase->purchase_number); ?></td><td><?php echo e($purchase->purchase_date->format('d M Y')); ?></td><td><?php echo e($purchase->warehouse->name); ?></td><td><?php echo e($purchase->supplier_name); ?></td><td><?php echo e($purchase->items()->count()); ?></td><td>$<?php echo e(number_format($purchase->total,2)); ?></td><td><span class="badge text-bg-<?php echo e($purchase->status==='received'?'success':'secondary'); ?>"><?php echo e(ucfirst($purchase->status)); ?></span></td></tr><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_1): ?><tr><td colspan="7" class="text-center py-5">No purchases yet. Record your first warehouse purchase.</td></tr><?php endif; ?></tbody></table></div>
